begin;

-- 1. CLÔTURER (déjà faits)
update public.tickets set status='Terminé', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Clôturé : couvert ailleurs (T169, T065/T200/T214, app en Expo).' end where ticket_code in ('T052','T077','T067') and status not in ('Terminé');

-- 2. ANCIENNE VERSION (n'a plus lieu d'être)
update public.tickets set status='Ancienne version', famille=null, quadrant='Q4', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Ancienne version — Ancienne vision : négociation / exécution automatique (Won''t)' end where ticket_code in ('T123','T124','T128','T222','T223','T224') and status not in ('Terminé');
update public.tickets set status='Ancienne version', famille=null, quadrant='Q4', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Ancienne version — Partenariats courtiers : recommander un produit nommé = intermédiation (ORIAS), exclu' end where ticket_code in ('T129','T130','T131') and status not in ('Terminé');
update public.tickets set status='Ancienne version', famille=null, quadrant='Q4', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Ancienne version — Tracker de budget : copierait Bankin'', hors besoin' end where ticket_code in ('T132','T134','T135','T136','T201','T204','T205','T206') and status not in ('Terminé');
update public.tickets set status='Ancienne version', famille=null, quadrant='Q4', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Ancienne version — Factures à venir : hors besoin' end where ticket_code in ('T045','T069','T083') and status not in ('Terminé');
update public.tickets set status='Ancienne version', famille=null, quadrant='Q4', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Ancienne version — Remplacé par le parcours porte ouverte (T246/T247)' end where ticket_code in ('T084') and status not in ('Terminé');
update public.tickets set status='Ancienne version', famille=null, quadrant='Q4', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Ancienne version — Remplacé : détection par règles actée, plus de ML' end where ticket_code in ('T068') and status not in ('Terminé');
update public.tickets set status='Ancienne version', famille=null, quadrant='Q4', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Ancienne version — Tranché : Powens retenu' end where ticket_code in ('T025','T027','T028') and status not in ('Terminé');
update public.tickets set status='Ancienne version', famille=null, quadrant='Q4', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Ancienne version — Fusionné dans un autre ticket (T002, T049, T254)' end where ticket_code in ('T015','T050','T158') and status not in ('Terminé');
update public.tickets set status='Ancienne version', famille=null, quadrant='Q4', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Ancienne version — Hors cadre : conseil fiscal réglementé, santé exclue, pas de recrutement CTO' end where ticket_code in ('T157','T159','T138') and status not in ('Terminé');

-- 3. GELÉ (autre famille ou après le PFE, dégelable)
update public.tickets set status='Gelé', famille='Après PFE', quadrant='Q4', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Gelé — Marketing et lancement, après décembre' end where ticket_code in ('T009','T010','T014','T020','T102','T103','T104','T105','T106','T107','T108','T109','T110','T111','T112','T113','T114','T115','T116','T117','T118','T119','T120','T121','T122') and status not in ('Terminé');
update public.tickets set status='Gelé', famille='Après PFE', quadrant='Q4', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Gelé — Juridique d''entreprise, après décembre' end where ticket_code in ('T022','T023','T030','T033','T034','T035','T036','T037','T162') and status not in ('Terminé');
update public.tickets set status='Gelé', famille='Après PFE', quadrant='Q4', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Gelé — Infra de production, inutile pour 10 testeurs' end where ticket_code in ('T053','T056','T059','T061','T062','T072','T076','T090','T091','T092','T093','T094','T095','T096','T097','T098','T099','T100','T215') and status not in ('Terminé');
update public.tickets set status='Gelé', famille='Après PFE', quadrant='Q4', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Gelé — Commission 30 % sur gain vérifié : après la V1' end where ticket_code in ('T126') and status not in ('Terminé');
update public.tickets set status='Gelé', famille='Après PFE', quadrant='Q4', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Gelé — Onboarding A/B : après la bêta' end where ticket_code in ('T137') and status not in ('Terminé');
update public.tickets set status='Gelé', famille='Après PFE', quadrant='Q4', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Gelé — Scale, Série A, international' end where ticket_code in ('T139','T140','T141','T142','T143','T144','T145','T146','T147','T148','T149','T150','T151','T152','T153','T154','T155','T156') and status not in ('Terminé');
update public.tickets set status='Gelé', famille='F6', quadrant='Q4', notes = case when coalesce(notes,'') like '%[22/10]%' then notes else coalesce(notes,'') || E'\n[22/10] Gelé — Famille 6 / V2 (couple et colocation)' end where ticket_code in ('T133') and status not in ('Terminé');

-- 4. REFORMULER (même numéro, nouveau sens)
update public.tickets set famille='F1', phase='P0', assignee='Basile', quadrant='Q1', fibonacci=3, title=$t$5 entretiens qualitatifs avec des actifs 26-35 ans$t$, description=$t$Compense l'échantillon du questionnaire (86 % de 18-25 ans, 89 % d'étudiants). Script Mom Test court + 2 questions prix (fusion de T015) : combien paierais-tu par service, que penses-tu de 30 % du gain du premier mois. Livrable : 5 comptes rendus + 1 page de synthèse pour le deck final.
Critère : entretiens faits avant le 27/11 (risque R6).$t$, status = case when 'F1' in ('F3','F4','F6') then 'Gelé' when status in ('Gelé','Ancienne version') then 'À faire' else status end where ticket_code='T002' and status not in ('Terminé');
update public.tickets set famille='F1', phase='P2', assignee='Aurore', quadrant='Q1', fibonacci=3, title=$t$Maquette de la porte ouverte (WebView + panneau de guidage)$t$, description=$t$Maquette de l'écran T246 avant de coder : page du prestataire plein écran, panneau repliable par-dessus avec les étapes, les infos à copier (bouton copier par champ), « C'est fait » et « Le lien ne marche pas ». Inclure les états : chargement, page en erreur, abonnement d'appli (renvoi vers les réglages du téléphone).
Critère : validée par l'équipe, utilisée par T246.$t$, status = case when 'F1' in ('F3','F4','F6') then 'Gelé' when status in ('Gelé','Ancienne version') then 'À faire' else status end where ticket_code='T046' and status not in ('Terminé');
update public.tickets set famille='F1', phase='P8', assignee='Aurore', quadrant='Q1', fibonacci=5, title=$t$10 testeurs réels sur l'app, parcours Basic-Fit de bout en bout$t$, description=$t$Jalon du 27/11. Recruter 10 testeurs (cible 20-30 ans, au moins 3 actifs), leur faire signer les CGU testeurs (T031), connecter leur vraie banque, laisser Alfred détecter, ouvrir la porte, puis vérifier au relevé suivant.
Mesures (T260) : ≥ 60 % des démarches ouvertes aboutissent (R2), 0 économie confirmée à tort (R3), < 10 % de liens signalés cassés (R5). Débrief court avec chaque testeur.
Prérequis : T031, T032, T261 signés (R4).$t$, status = case when 'F1' in ('F3','F4','F6') then 'Gelé' when status in ('Gelé','Ancienne version') then 'À faire' else status end where ticket_code='T049' and status not in ('Terminé');
update public.tickets set famille='F1', phase='P5', assignee='Maxence', quadrant='Q1', fibonacci=3, title=$t$Mobile : volet « Alfred relance » (prélevé après résiliation)$t$, description=$t$Quand T239 détecte un prélèvement après une résiliation confirmée par l'utilisateur, l'action passe en relance. Écran : montant prélevé à tort, date, texte de contestation prêt (T240), et marche à suivre pour demander le remboursement SEPA dans l'appli de sa banque (8 semaines, sans justification).
Critère : le parcours est testable avec un prélèvement simulé en sandbox.$t$, status = case when 'F1' in ('F3','F4','F6') then 'Gelé' when status in ('Gelé','Ancienne version') then 'À faire' else status end where ticket_code='T085' and status not in ('Terminé');
update public.tickets set famille='F4', phase='P9', assignee='Basile', quadrant='Q4', fibonacci=5, title=$t$Famille 4 : vol retardé ou non pris, porte ouverte vers le formulaire de la compagnie$t$, description=$t$V1.5. Après un achat de billet d'avion, une question d'un tap après la date du vol : « Plus de 3 h de retard ? » / « Tu as pris ce vol ? ». Ouvre le formulaire de la compagnie avec le texte prêt : 250 à 600 € selon la distance (règlement CE 261/2004), ou remboursement des taxes d'aéroport pour un vol non pris. Pas d'API FlightStats en V1.5.$t$, status = case when 'F4' in ('F3','F4','F6') then 'Gelé' when status in ('Gelé','Ancienne version') then 'À faire' else status end where ticket_code='T125' and status not in ('Terminé');
update public.tickets set famille='F1', phase='P4', assignee='Basile', quadrant='Q2', fibonacci=3, title=$t$Lettres par gabarit en plan B (résiliation, renonciation, mise en demeure)$t$, description=$t$Should. Quand la procédure de l'annuaire est « letter » ou quand la page ne marche pas, Alfred propose une lettre prête par gabarit, remplie avec les infos de l'abonnement. Aucune génération par IA en V1. Gabarits : résiliation simple, résiliation loi Hamon, contestation de prélèvement.
Critère : 3 gabarits, test unitaire par gabarit, l'utilisateur copie ou télécharge le texte.$t$, status = case when 'F1' in ('F3','F4','F6') then 'Gelé' when status in ('Gelé','Ancienne version') then 'À faire' else status end where ticket_code='T127' and status not in ('Terminé');
update public.tickets set famille='F6', phase='P9', assignee='Maxence', quadrant='Q4', fibonacci=8, title=$t$Famille 6 : cagnotte virtuelle (économies prouvées + argent récupéré + arrondis)$t$, description=$t$V2. Cagnotte vers un objectif, alimentée par les économies confirmées sur le relevé, l'argent récupéré (familles 4 et 5) et les arrondis à l'euro supérieur. Virtuelle : aucun argent déplacé, donc pas d'agrément. Préparer seulement le calcul du montant moyen des arrondis sur les 273 transactions pour la soutenance finale.$t$, status = case when 'F6' in ('F3','F4','F6') then 'Gelé' when status in ('Gelé','Ancienne version') then 'À faire' else status end where ticket_code='T160' and status not in ('Terminé');
update public.tickets set famille='F1', phase='P4', assignee='Hippo', quadrant='Q1', fibonacci=3, title=$t$Connecter 5 vrais comptes Powens (équipe) pour tester la vérification$t$, description=$t$Réassigné de Greg à Hippo. 5 comptes réels de l'équipe connectés en continu jusqu'à décembre, pour avoir des relevés successifs et tester T239 sur de vraies données avant les testeurs.$t$, status = case when 'F1' in ('F3','F4','F6') then 'Gelé' when status in ('Gelé','Ancienne version') then 'À faire' else status end where ticket_code='T161' and status not in ('Terminé');
update public.tickets set famille='F3', phase='P9', assignee='Hippo', quadrant='Q4', fibonacci=3, title=$t$Profil utilisateur pour les règles (étudiant / actif, déménagement récent)$t$, description=$t$V1.5, sert la famille 3. Deux ou trois questions d'un tap à l'onboarding ou au premier moment détecté : étudiant ou actif, logement récent. Utilisé pour ne pas proposer une offre étudiante à un actif et pour déclencher la liste « déménagement ».$t$, status = case when 'F3' in ('F3','F4','F6') then 'Gelé' when status in ('Gelé','Ancienne version') then 'À faire' else status end where ticket_code='T216' and status not in ('Terminé');
update public.tickets set famille='F1', phase='P4', assignee='Hippo', quadrant='Q1', fibonacci=3, title=$t$Détection : hausse de prix silencieuse transformée en proposition$t$, description=$t$La détection des hausses existe pour l'écran Analyse (list_price_changes). La transformer en proposition : « +2 € par mois depuis mars, ça vaut le coup ? », avec la porte ouverte vers la page de résiliation. Seuil : hausse ≥ 5 % ou ≥ 1 € sur deux prélèvements consécutifs du même marchand.
Critère : tests sur 3 cas (hausse, baisse, promo terminée), pas de doublon de proposition.$t$, status = case when 'F1' in ('F3','F4','F6') then 'Gelé' when status in ('Gelé','Ancienne version') then 'À faire' else status end where ticket_code='T220' and status not in ('Terminé');
update public.tickets set famille='F1', phase='P4', assignee='Hippo', quadrant='Q1', fibonacci=2, title=$t$next_expected_at fiable (socle de la vérification)$t$, description=$t$Bug : la date du prochain prélèvement est parfois déjà passée. La vérification T239 en dépend : recalculer next_expected_at à chaque synchro à partir de la périodicité détectée (mensuel, annuel), jamais dans le passé.
Critère : test sur un abonnement mensuel et un annuel, aucune date passée en base après synchro.$t$, status = case when 'F1' in ('F3','F4','F6') then 'Gelé' when status in ('Gelé','Ancienne version') then 'À faire' else status end where ticket_code='T229' and status not in ('Terminé');
update public.tickets set famille='F1', phase='P1', assignee='Basile', quadrant='Q1', fibonacci=3, title=$t$CGU version testeurs (information, pas de conseil)$t$, description=$t$Obligatoire avant les testeurs (R4). Version courte rédigée par l'équipe, sans avocat : Alfred informe et ouvre la page, ne résilie pas à la place de l'utilisateur, ne lit ni ne stocke d'identifiants, ne recommande aucun produit nommé, aucune garantie d'économie. Acceptation obligatoire dans l'app (case + date).
Critère : texte relu par l'équipe, écran d'acceptation branché.$t$, status = case when 'F1' in ('F3','F4','F6') then 'Gelé' when status in ('Gelé','Ancienne version') then 'À faire' else status end where ticket_code='T031' and status not in ('Terminé');
update public.tickets set famille='F1', phase='P1', assignee='Basile', quadrant='Q1', fibonacci=2, title=$t$Politique de confidentialité version testeurs$t$, description=$t$Obligatoire avant les testeurs (R4). Données collectées (transactions via Powens), finalité, durée de conservation, sous-traitants (Powens, Supabase, Anthropic si T252), droits et suppression du compte (s'appuie sur T221 purge RGPD).
Critère : page accessible depuis le profil et l'onboarding.$t$, status = case when 'F1' in ('F3','F4','F6') then 'Gelé' when status in ('Gelé','Ancienne version') then 'À faire' else status end where ticket_code='T032' and status not in ('Terminé');

